cd /repo/evals/terraform-secure-iac/results/raw/2026-11-05/tsi-01-remote-state/with-skill/run-2/workspace
mkdir bootstrap
cat > .gitignore <<'E'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
crash.*.log
*.tfvars
*.auto.tfvars
E
cat > bootstrap/versions.tf <<'E'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
E
cat > bootstrap/providers.tf <<'E'
provider "aws" {
  region = var.region
}
E
cat > bootstrap/variables.tf <<'E'
variable "region" {
  type        = string
  default     = "eu-north-1"
  description = "AWS region in which the state bucket and its encryption key are created."
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that stores Terraform state. Bucket names are global, so the name must be unique across AWS."

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name))
    error_message = "The bucket name must be 3 to 63 characters of lowercase letters, digits, dots, and hyphens."
  }
}

variable "noncurrent_version_retention_days" {
  type        = number
  default     = 90
  description = "Number of days a superseded state version is kept before it is deleted. Versions inside this window can be restored."
}
E
cat > bootstrap/main.tf <<'E'
resource "aws_kms_key" "state" {
  description         = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation = true
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
E
cat > bootstrap/outputs.tf <<'E'
output "state_bucket_name" {
  value       = aws_s3_bucket.state.id
  description = "Name of the state bucket, for the bucket argument of the backend block."
}

output "state_kms_key_arn" {
  value       = aws_kms_key.state.arn
  description = "ARN of the key that encrypts state. Principals that run Terraform need kms:Encrypt, kms:Decrypt, and kms:GenerateDataKey on it."
}
E
cat > backend.tf <<'E'
# The bucket is created by bootstrap/. Replace the placeholder name with the
# value of that configuration's state_bucket_name before running init.
terraform {
  backend "s3" {
    bucket       = "example-reports-tfstate"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
E
terraform fmt -recursive -check -diff; (cd bootstrap && terraform init -backend=false >/dev/null && terraform validate); checkov -d bootstrap --quiet --compact 2>&1 | tail -30

